// real, src/spot.ts
confirm(ticketId: string): void {
  if (this.current !== "reserved" || this.holder !== ticketId) {
    throw new ParkingError("SPOT_STATE", `spot ${this.id} is not reserved by ticket ${ticketId}`);
  }
  this.current = "occupied";
}

// real, src/timeout.ts
export async function withTimeout<T>(work: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
  const controller = new AbortController();
  let timer: NodeJS.Timeout | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      controller.abort();
      reject(new Error(`no answer within ${timeoutMs} ms`));
    }, timeoutMs);
  });
  try {
    return await Promise.race([(async () => work(controller.signal))(), timeout]);
  } finally {
    clearTimeout(timer);
  }
}

