// illustrative solution, NOT in the repo -- src/parking-lot.ts
// Cancels reservations older than maxAgeMs (a gate that died between reserve and confirm/cancel).
// maxAgeMs must be well above every gate's device timeout, or a live gate loses its claim.
expireReservations(maxAgeMs: number): string[] {
  const now = this.clock.now();
  const old = [...this.entries.values()]
    .filter((e) => e.status === "reserved" && now - e.ticket.entryAt > maxAgeMs)
    .map((e) => e.ticket.id);
  const expired: string[] = [];
  for (const id of old) {
    if (this.entries.get(id)?.status !== "reserved") continue; // a listener may have changed it
    this.cancel(id);
    expired.push(id);
  }
  return expired;
}

// test/two-phase.test.ts (uses the file's makeLot and code helpers)
it("expireReservations cancels only reservations older than maxAge", () => {
  const { lot, clock } = makeLot([["compact", "compact"]]);
  const old = lot.reserve("A1", "car");     // its gate crashed here
  clock.advance(60_000);
  const fresh = lot.reserve("A2", "car");
  clock.advance(1);
  expect(lot.expireReservations(60_000)).toEqual([old.id]);
  expect(lot.statusOf(old.id)).toBeUndefined();
  expect(lot.statusOf(fresh.id)).toBe("reserved");
  expect(lot.availability()[0]!.free).toBe(1);
  expect(code(() => lot.confirm(old.id))).toBe("RESERVATION_NOT_FOUND"); // the late gate
  expect(lot.reserve("A1", "car").spotId).toBe("L0-1");               // plate and spot are free again
});

