    expect(device.calls).toHaveLength(2); // two barriers for one ticket
    device.calls.forEach((c) => c.resolve());
    const r = await Promise.allSettled([p1, p2]);
    expect(r.map((x) => x.status)).toEqual(["fulfilled", "rejected"]);
  }
  // the fix
  {
    const { lot } = makeLot([["compact"]]);
    const t = lot.park("A1", "car");
    const device = new FakeDevice();
    const p1 = new ExitGate(lot, device).leave(t.id);
    const p2 = new ExitGate(lot, device).leave(t.id);
    await expect(p2).rejects.toMatchObject({ code: "TICKET_BUSY" });
    await flush();
    expect(device.calls).toHaveLength(1);
    device.calls[0]!.resolve();
    await p1;
    expect(lot.statusOf(t.id)).toBeUndefined();
  }
});

// illustrative driver, NOT in the repo: how a real barrier driver would honour the signal
async issue(ticket: Ticket, signal: AbortSignal): Promise<void> {
  await this.printer.print(ticket, { signal });          // pass it down where the API supports it
  if (signal.aborted) throw signal.reason;              // gate gave up while printing: do NOT open
  await this.barrier.open();                             // point of no return
}

